<script setup>
import { computed, ref, watch } from 'vue'
import { SHOPPING_APP_PAGE_EVENTS, SHOPPING_APP_PAGE_PROPS, localizeAppPage } from './shopping-app-page-contract'
import Shopping29CmMedia from '../Shopping29CmMedia.vue'
import { shopping29cmMediaSource, shopping29cmOwnerNotes, shopping29cmProductMedia, shopping29cmProductTone, shopping29cmStateSource } from '../shopping-29cm-media'

const props = defineProps(SHOPPING_APP_PAGE_PROPS)
const emit = defineEmits(SHOPPING_APP_PAGE_EVENTS)
const localize = (zh, en) => localizeAppPage(props.languageBase, zh, en)
const mediaRole = ref('main')
const quantity = ref(1)
const sortMode = ref('recommended')
const reviewFilter = ref('all')
const activeProductSection = ref('details')
const productSource = (product, role = 'main') => shopping29cmMediaSource(shopping29cmProductMedia(product?.id, role)) || props.productImageUrl(product)
const productTone = (product) => shopping29cmProductTone(product?.id)
const productAlt = (product, role = 'main') => props.productDisplayTitle(product) + ' / 29CM ' + role
const mediaOptions = computed(() => [
  { key: 'main', zh: '完整物件', en: 'OBJECT' },
  { key: 'detail', zh: '材质细节', en: 'DETAIL' },
  { key: 'context', zh: '使用场景', en: 'IN LIFE' },
])
const selectedMediaLabel = computed(() => mediaOptions.value.find((item) => item.key === mediaRole.value) || mediaOptions.value[0])
const displayProducts = computed(() => {
  const products = [...(props.products || [])]
  if (sortMode.value === 'price-low') return products.sort((a, b) => a.priceCents - b.priceCents)
  if (sortMode.value === 'price-high') return products.sort((a, b) => b.priceCents - a.priceCents)
  return products
})
const ownerNotes = computed(() => shopping29cmOwnerNotes(props.product?.id))
const visibleOwnerNotes = computed(() => reviewFilter.value === 'all' ? ownerNotes.value : ownerNotes.value.filter((note) => note.role === reviewFilter.value))
const averageRating = computed(() => ownerNotes.value.length
  ? (ownerNotes.value.reduce((sum, note) => sum + note.rating, 0) / ownerNotes.value.length).toFixed(1)
  : '—')
const emptyCollectionSource = computed(() => shopping29cmStateSource('collection'))
const resetCollectionSearch = () => {
  emit('update:searchQuery', '')
  emit('select-category', props.category?.key || 'digital')
}
watch(() => props.product?.id, () => {
  activeProductSection.value = 'details'
  mediaRole.value = 'main'
  reviewFilter.value = 'all'
  quantity.value = 1
})
</script>

<template>
  <main class="cm-pages" :data-page="pageKey" data-testid="shopping-store-specific-page">
    <header class="cm-page-bar"><button type="button" :aria-label="localize('返回上一页', 'Back')" @click="emit('back')"><i class="fas fa-arrow-left" aria-hidden="true"></i></button><div><span>29CM / SEOUL</span><strong>{{ serviceLabel || '29CM' }}</strong></div><div><button type="button" :aria-label="localize('订单', 'Orders')" @click="emit('open-orders')">{{ localize('订单', 'ORDERS') }}</button><button type="button" data-testid="shopping-page-cart" :aria-label="localize('购物袋', 'Shopping bag')" @click="emit('open-cart')">{{ localize('购物袋', 'BAG') }} <b v-if="cartQuantity">{{ cartQuantity }}</b></button></div></header>

    <template v-if="pageKey === 'category'">
      <section class="cm-collection-intro"><div><span>SHOP / {{ category?.label || 'ALL' }}</span><h1>{{ category?.label || localize('全部商品', 'All products') }}</h1><p>{{ searchQuery ? localize('当前搜索结果，可继续按分类与价格排序。', 'Search results ready to compare by category and price.') : localize('比较价格、库存与配送，再进入商品详情。', 'Compare price, availability, and delivery before opening a product.') }}</p></div><aside><b>{{ String(totalCount).padStart(2, '0') }}</b><span>{{ localize('件商品', 'PRODUCTS') }}</span></aside></section>
      <form class="cm-collection-search" role="search" @submit.prevent="emit('submit-search')"><span>SEARCH /</span><input type="search" :aria-label="localize('搜索商品', 'Search products')" :value="searchQuery" :placeholder="localize('品牌、设计师、商品', 'Brand, designer, product')" @input="emit('update:searchQuery', $event.target.value)" /><button type="submit" :aria-label="localize('提交搜索', 'Submit search')"><i class="fas fa-arrow-right" aria-hidden="true"></i></button></form>
      <nav class="cm-collection-index" :aria-label="localize('分类目录', 'Category index')"><button v-for="item in categories" :key="item.key" type="button" :class="{ 'is-active': item.key === category?.key }" :aria-current="item.key === category?.key ? 'page' : undefined" @click="emit('select-category', item.key)"><span>{{ item.label }}</span><small>{{ String(item.count).padStart(2, '0') }}</small></button></nav>
      <div class="cm-commerce-toolbar"><span>{{ totalCount }} {{ localize('件结果', 'RESULTS') }}</span><label>{{ localize('排序', 'SORT') }}<select v-model="sortMode"><option value="recommended">{{ localize('推荐顺序', 'Recommended') }}</option><option value="price-low">{{ localize('价格从低到高', 'Price: low to high') }}</option><option value="price-high">{{ localize('价格从高到低', 'Price: high to low') }}</option></select></label></div>
      <div v-if="displayProducts.length === 0" class="cm-page-empty"><Shopping29CmMedia :src="emptyCollectionSource" :alt="localize('空的商品目录', 'Empty product collection')" eyebrow="COLLECTION / EMPTY" label="—" tone="paper" role="state" icon="fas fa-compass" /><div><span>{{ searchQuery ? 'SEARCH / 00' : 'INDEX / WAITING' }}</span><h2>{{ searchQuery ? localize('没有匹配结果。', 'No matching products.') : localize('该分类暂时没有商品。', 'No products are available in this category yet.') }}</h2><button type="button" @click="searchQuery ? resetCollectionSearch() : emit('back')">{{ searchQuery ? localize('清除搜索', 'CLEAR SEARCH') : localize('返回首页', 'BACK HOME') }}</button></div></div>
      <section v-else class="cm-collection-flow"><article v-for="product in displayProducts" :key="product.id" class="cm-collection-item" :data-testid="'shopping-product-' + product.id"><button type="button" class="cm-collection-media" @click="emit('open-product', product.id)"><Shopping29CmMedia :src="productSource(product)" :alt="productAlt(product)" :eyebrow="serviceLabel || '29CM'" :label="props.productDisplayTitle(product)" :tone="productTone(product)" icon="fas fa-cube" /></button><div class="cm-collection-copy cm-object-copy"><div class="cm-collection-meta"><span>{{ serviceLabel || '29CM' }}</span><button type="button" :aria-label="localize('收藏或取消收藏', 'Toggle favorite')" :class="{ 'is-favorite': props.isProductFavorite(product.id) }" @click="emit('toggle-favorite', product.id)"><i class="fas fa-heart" aria-hidden="true"></i></button></div><button type="button" class="cm-object-title" @click="emit('open-product', product.id)">{{ props.productDisplayTitle(product) }}</button><p>{{ props.productDisplayDescription(product) }}</p><div class="cm-card-commerce"><strong>{{ props.formatPrice(product) }}</strong><span>{{ props.stockStatusLabel(product.stockStatus) }}</span><small><i class="fas fa-truck" aria-hidden="true"></i>{{ localize('首尔圈预计 1–3 日送达', 'Seoul delivery in 1–3 days') }}</small></div><div><button type="button" class="cm-read-link" @click="emit('open-product', product.id)">{{ localize('查看商品', 'VIEW PRODUCT') }} <i class="fas fa-arrow-right" aria-hidden="true"></i></button><button type="button" class="cm-quick-add" :disabled="product.stockStatus === 'sold_out'" :data-testid="'shopping-add-cart-' + product.id" @click="emit('add-to-cart', product.id)">{{ localize('加入购物袋', 'ADD TO BAG') }}</button></div></div></article></section>
      <nav v-if="pageCount > 1" class="cm-page-nav" data-testid="shopping-pagination"><button type="button" :disabled="page <= 1" @click="emit('change-page', page - 1)">← {{ localize('上一页', 'PREVIOUS') }}</button><span>{{ String(page).padStart(2, '0') }} / {{ String(pageCount).padStart(2, '0') }}</span><button type="button" :disabled="page >= pageCount" @click="emit('change-page', page + 1)">{{ localize('下一页', 'NEXT') }} →</button></nav>
    </template>

    <template v-else-if="product">
      <section class="cm-pdp-intro"><div class="cm-pdp-media"><Shopping29CmMedia :src="productSource(product, mediaRole)" :alt="productAlt(product, mediaRole)" :eyebrow="selectedMediaLabel.en" :label="props.productDisplayTitle(product)" :tone="productTone(product)" :role="mediaRole === 'context' ? 'context' : 'object'" icon="fas fa-cube" /><div class="cm-pdp-media-tabs"><button v-for="item in mediaOptions" :key="item.key" type="button" :class="{ 'is-active': mediaRole === item.key }" @click="mediaRole = item.key"><span>{{ item.en }}</span><small>{{ localize(item.zh, item.en) }}</small></button></div></div><div class="cm-pdp-copy"><span class="cm-pdp-kicker">29CM / PRODUCT</span><h1>{{ props.productDisplayTitle(product) }}</h1><p>{{ props.productDisplayDescription(product) }}</p><div class="cm-review-summary"><button type="button" :disabled="!ownerNotes.length" @click="activeProductSection = 'reviews'"><i class="fas fa-camera" aria-hidden="true"></i>{{ ownerNotes.length }} {{ localize('条图片评价', 'photo reviews') }} <i class="fas fa-chevron-right" aria-hidden="true"></i></button></div><div class="cm-pdp-facts"><span><small>{{ localize('库存', 'AVAILABILITY') }}</small><b>{{ props.stockStatusLabel(product.stockStatus) }}</b></span><span><small>{{ localize('销售方', 'SOLD BY') }}</small><b>{{ serviceLabel || '29CM' }}</b></span></div><strong class="cm-pdp-price">{{ props.formatPrice(product) }}</strong><section class="cm-purchase-confidence"><div><i class="fas fa-truck-fast" aria-hidden="true"></i><span><b>{{ localize('预计 1–3 日送达', 'Estimated delivery in 1–3 days') }}</b><small>{{ localize('结算时确认地址与配送费', 'Address and fee confirmed at checkout') }}</small></span></div><div><i class="fas fa-rotate-left" aria-hidden="true"></i><span><b>{{ localize('支持退换申请', 'Returns available') }}</b><small>{{ localize('以订单状态与商品情况为准', 'Subject to order and item condition') }}</small></span></div></section><div class="cm-quantity-row"><span>{{ localize('数量', 'QUANTITY') }}</span><div><button type="button" :disabled="quantity <= 1" @click="quantity--">−</button><b>{{ quantity }}</b><button type="button" @click="quantity++">+</button></div></div><div class="cm-pdp-actions"><button type="button" :class="{ 'is-saved': props.isProductFavorite(product.id) }" @click="emit('toggle-favorite', product.id)"><i class="fas fa-heart" aria-hidden="true"></i>{{ localize('收藏', 'SAVE') }}</button><button type="button" data-testid="shopping-product-add" :disabled="product.stockStatus === 'sold_out'" @click="emit('add-to-cart', product.id, quantity)">{{ product.stockStatus === 'sold_out' ? localize('暂时售罄', 'SOLD OUT') : localize('加入购物袋', 'ADD TO BAG') }} <i class="fas fa-arrow-right" aria-hidden="true"></i></button></div></div></section>
      <nav class="cm-pdp-jump" role="tablist" :aria-label="localize('商品信息分区', 'Product information')"><button type="button" role="tab" :aria-selected="activeProductSection === 'details'" :class="{ 'is-active': activeProductSection === 'details' }" @click="activeProductSection = 'details'">{{ localize('商品详情', 'Details') }}</button><button type="button" role="tab" :aria-selected="activeProductSection === 'reviews'" :class="{ 'is-active': activeProductSection === 'reviews' }" :disabled="!ownerNotes.length" @click="activeProductSection = 'reviews'">{{ localize('评价', 'Reviews') }} {{ ownerNotes.length }}</button><button type="button" role="tab" :aria-selected="activeProductSection === 'delivery'" :class="{ 'is-active': activeProductSection === 'delivery' }" @click="activeProductSection = 'delivery'">{{ localize('配送与退换', 'Delivery & returns') }}</button></nav>
      <template v-if="activeProductSection === 'details'"><section id="cm-details" class="cm-pdp-note"><header><span>01</span><p>PRODUCT SUMMARY</p></header><div><h2>{{ localize('先确认用途，再看材质与场景。', 'Start with use, then inspect material and context.') }}</h2><p>{{ props.productDisplayDescription(product) }}</p></div></section><section class="cm-pdp-detail"><div><span>02 / MATERIAL</span><h2>{{ localize('材料会决定它如何进入生活。', 'Material decides how it enters life.') }}</h2><p>{{ localize('以下内容只描述可观察的触感与维护方向；规格、价格与库存始终由页面代码表达。', 'This section describes observable tactility and care. Specifications, price, and stock remain code-rendered.') }}</p></div><Shopping29CmMedia :src="productSource(product, 'detail')" :alt="productAlt(product, 'detail')" eyebrow="MATERIAL / DETAIL" label="02" :tone="productTone(product)" role="material" icon="fas fa-grip-lines" /></section><section class="cm-pdp-context"><Shopping29CmMedia :src="productSource(product, 'context')" :alt="productAlt(product, 'context')" eyebrow="OBJECTS IN USE" label="03" :tone="productTone(product)" role="context" icon="fas fa-table-cells-large" /><div><span>03 / IN LIFE</span><h2>{{ localize('不是展示它，而是想象它被反复使用。', 'Not displayed. Repeatedly used.') }}</h2><p>{{ localize('场景图只帮助理解尺度、位置与相邻物件，不承诺超出订单事实的生活方式。', 'The context image clarifies scale, placement, and neighboring objects without promising a lifestyle beyond the order facts.') }}</p></div></section><section v-if="relatedProducts.length" class="cm-related"><header><span>04 / RELATED PRODUCTS</span><h2>{{ localize('你也可以比较这些商品', 'More products to compare') }}</h2></header><div><button v-for="related in relatedProducts.slice(0, 4)" :key="related.id" type="button" @click="emit('open-product', related.id)"><Shopping29CmMedia :src="productSource(related)" :alt="productAlt(related)" eyebrow="RELATED" label="+" :tone="productTone(related)" icon="fas fa-cube" /><strong>{{ props.productDisplayTitle(related) }}</strong><small>{{ props.formatPrice(related) }}</small></button></div></section></template>
      <section v-else-if="activeProductSection === 'reviews' && ownerNotes.length" id="cm-reviews" class="cm-owner-notes" data-testid="shopping-29cm-owner-notes"><header><div><span>CUSTOMER REVIEWS</span><h2>{{ localize('购买者评价', 'Customer reviews') }}</h2></div><div class="cm-owner-overview"><strong>{{ averageRating }}</strong><div class="cm-stars" :aria-label="localize('平均 ' + averageRating + ' 分', averageRating + ' average rating')"><i v-for="index in 5" :key="index" :class="index <= Math.round(Number(averageRating)) ? 'fas fa-star' : 'far fa-star'" aria-hidden="true"></i></div><span>{{ ownerNotes.length }} {{ localize('条含图评价', 'reviews with photos') }}</span></div></header><div class="cm-review-filters"><button type="button" :class="{ 'is-active': reviewFilter === 'all' }" @click="reviewFilter = 'all'">{{ localize('全部', 'All') }} {{ ownerNotes.length }}</button><button type="button" :class="{ 'is-active': reviewFilter === 'scene' }" @click="reviewFilter = 'scene'">{{ localize('使用体验', 'In use') }}</button><button type="button" :class="{ 'is-active': reviewFilter === 'detail' }" @click="reviewFilter = 'detail'">{{ localize('做工细节', 'Details') }}</button><button type="button" :class="{ 'is-active': reviewFilter === 'follow-up' }" @click="reviewFilter = 'follow-up'">{{ localize('追评', 'Follow-up') }}</button></div><div class="cm-review-list"><article v-for="note in visibleOwnerNotes" :key="note.id" class="cm-review-card"><header><div><span class="cm-review-avatar">{{ note.owner }}</span><div><strong>{{ note.owner }}</strong><div class="cm-stars" :aria-label="localize(note.rating + ' 分', note.rating + ' stars')"><i v-for="index in 5" :key="index" :class="index <= note.rating ? 'fas fa-star' : 'far fa-star'" aria-hidden="true"></i></div></div></div><time>{{ note.date }}</time></header><dl class="cm-review-specs"><div><dt>{{ localize('购买规格', 'Purchased option') }}</dt><dd>{{ languageBase === 'zh' ? note.optionZh : note.optionEn }}</dd></div><div><dt>{{ localize('使用周期', 'Usage period') }}</dt><dd>{{ languageBase === 'zh' ? note.periodZh : note.periodEn }}</dd></div></dl><div class="cm-review-body"><Shopping29CmMedia :src="shopping29cmMediaSource(note)" :alt="localize('购买者实拍：' + props.productDisplayTitle(product), 'Customer photo for ' + props.productDisplayTitle(product))" :eyebrow="note.role === 'follow-up' ? 'FOLLOW-UP' : 'CUSTOMER PHOTO'" :label="note.owner" :tone="productTone(product)" role="owner" icon="fas fa-camera" /><div><p>{{ languageBase === 'zh' ? note.noteZh : note.noteEn }}</p><div class="cm-review-metrics"><div v-for="(score, index) in note.scores" :key="index"><span>{{ languageBase === 'zh' ? note.metricsZh[index] : note.metricsEn[index] }}</span><div><i :style="{ width: (score / 5 * 100) + '%' }"></i></div><b>{{ score }}</b></div></div></div></div><footer><span><i class="fas fa-camera" aria-hidden="true"></i>{{ localize('含实拍图片', 'Photo included') }}</span><span>{{ note.role === 'follow-up' ? localize('使用后追评', 'Follow-up review') : localize('购买后评价', 'Post-purchase review') }}</span></footer></article></div></section>
      <section v-else id="cm-delivery" class="cm-pdp-care"><div><span>DELIVERY & CARE</span><h2>{{ localize('配送、退换与保养', 'Delivery, returns, and care') }}</h2></div><dl><div><dt>{{ localize('配送', 'DELIVERY') }}</dt><dd>{{ localize('首尔圈预计 1–3 日送达，最终时间与费用在结算页确认。', 'Estimated Seoul delivery in 1–3 days; final timing and fees appear at checkout.') }}</dd></div><div><dt>{{ localize('退换', 'RETURNS') }}</dt><dd>{{ localize('可从订单详情发起退换申请，是否可退以订单状态与商品情况为准。', 'Start a return from order details; eligibility depends on order and item condition.') }}</dd></div><div><dt>{{ localize('保养', 'CARE') }}</dt><dd>{{ localize('以柔软干布清洁，并避免长时间潮湿与强光直射。', 'Use a soft dry cloth and avoid prolonged moisture or harsh direct light.') }}</dd></div></dl></section>
    </template>
  </main>
</template>
<style scoped>
